<?php
if (!defined('ABSPATH')) exit;
/** Optional Shippo integration. Keys never reach the browser. */
final class ERM_Shippo {
 static function init(){
  add_action('admin_menu',[__CLASS__,'menu']);
  add_action('admin_post_erm_shippo_settings',[__CLASS__,'save']);
  add_action('wp_ajax_erm_shippo_rates',[__CLASS__,'rates']);
  add_action('wp_ajax_nopriv_erm_shippo_rates',[__CLASS__,'rates']);
  add_action('admin_post_erm_shippo_label',[__CLASS__,'label']);
 }
 static function options(){return wp_parse_args((array)get_option('erm_shippo',[]),['token'=>'','test'=>1,'name'=>'','street1'=>'','city'=>'','state'=>'','zip'=>'','country'=>'US','phone'=>'','weight'=>'1','length'=>'8','width'=>'6','height'=>'4']);}
 static function configured(){ $s=self::options();return $s['token']!==''&&$s['street1']!==''&&$s['zip']!==''&&$s['city']!=='';}
 static function menu(){add_submenu_page('edit.php?post_type=erm_event','Shipping Settings','Shipping Settings','manage_options','erm-shipping-settings',[__CLASS__,'page']);add_submenu_page('edit.php?post_type=erm_event','Shipping Labels','Shipping Labels','manage_options','erm-shipping-labels',[__CLASS__,'labels_page']);}
 static function page(){if(!current_user_can('manage_options'))wp_die('Forbidden');$s=self::options();echo '<div class="wrap"><h1>Shippo — Shipping Settings</h1><p>Connect Shippo for carrier rates and label printing. Your API token stays on the server. Test mode should be used before purchasing live labels.</p>';
  if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Shipping settings saved.</p></div>';
  echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="erm_shippo_settings">';wp_nonce_field('erm_shippo_settings');
  $fields=['token'=>'Shippo API token','name'=>'Sender name / business','street1'=>'Sender street','city'=>'Sender city','state'=>'Sender state/province','zip'=>'Sender postal code','country'=>'Sender country (ISO 2 letters)','phone'=>'Sender phone','weight'=>'Default package weight (lb)','length'=>'Package length (in)','width'=>'Package width (in)','height'=>'Package height (in)'];
  echo '<table class="form-table">';foreach($fields as $key=>$label){echo '<tr><th><label for="erm_shippo_'.esc_attr($key).'">'.esc_html($label).'</label></th><td><input class="regular-text" id="erm_shippo_'.esc_attr($key).'" type="'.($key==='token'?'password':'text').'" autocomplete="off" name="shippo['.esc_attr($key).']" value="'.esc_attr($key==='token'?'':$s[$key]).'" placeholder="'.($key==='token'&&$s['token']?'Saved — leave blank to keep':'').'"></td></tr>';}
  echo '<tr><th>Mode</th><td><label><input type="checkbox" name="shippo[test]" value="1" '.checked(!empty($s['test']),true,false).'> Test mode (recommended for setup)</label><p>Use a Shippo test token for test mode. Switching modes does not transform a test token into a live token.</p></td></tr></table><p><button class="button button-primary">Save Shipping Settings</button></p></form></div>';
 }
 static function save(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('erm_shippo_settings');$raw=isset($_POST['shippo'])&&is_array($_POST['shippo'])?wp_unslash($_POST['shippo']):[];$old=self::options();$new=[];foreach(['name','street1','city','state','zip','country','phone'] as $k)$new[$k]=substr(sanitize_text_field($raw[$k]??''),0,150);$new['country']=strtoupper($new['country']);if(!preg_match('/^[A-Z]{2}$/',$new['country']))$new['country']='US';foreach(['weight','length','width','height'] as $k)$new[$k]=(string)max(0.1,min(1000,(float)($raw[$k]??1)));$new['test']=empty($raw['test'])?0:1;$token=trim((string)($raw['token']??''));$new['token']=$token!==''?sanitize_text_field($token):$old['token'];update_option('erm_shippo',$new,false);wp_safe_redirect(admin_url('edit.php?post_type=erm_event&page=erm-shipping-settings&saved=1'));exit;}
 static function request($endpoint,$data){$o=self::options();if(!$o['token'])return new WP_Error('shippo','Shipping provider is not configured.');$url='https://api.goshippo.com/'.ltrim($endpoint,'/');$response=wp_safe_remote_post($url,['timeout'=>20,'redirection'=>0,'headers'=>['Authorization'=>'ShippoToken '.$o['token'],'Content-Type'=>'application/json','SHIPPO-API-VERSION'=>'2018-02-08'],'body'=>wp_json_encode($data)]);if(is_wp_error($response))return $response;$code=wp_remote_retrieve_response_code($response);$body=json_decode(wp_remote_retrieve_body($response),true);if($code<200||$code>=300||!is_array($body))return new WP_Error('shippo','Carrier service returned an error (HTTP '.(int)$code.').');return $body;}
 static function shipment($address){$o=self::options();return ['address_from'=>['name'=>$o['name']?:'Shipping Department','street1'=>$o['street1'],'city'=>$o['city'],'state'=>$o['state'],'zip'=>$o['zip'],'country'=>$o['country'],'phone'=>$o['phone']],'address_to'=>['name'=>'Customer','street1'=>$address['street'],'city'=>$address['city'],'state'=>$address['region'],'zip'=>$address['postcode'],'country'=>strtoupper($address['country'])],'parcels'=>[['length'=>$o['length'],'width'=>$o['width'],'height'=>$o['height'],'distance_unit'=>'in','weight'=>$o['weight'],'mass_unit'=>'lb']],'async'=>false];}
 static function address_from_post(){ $address=[];foreach(['country'=>2,'postcode'=>20,'street'=>180,'city'=>100,'region'=>100] as $key=>$length)$address[$key]=substr(sanitize_text_field(wp_unslash($_POST['erm_ship_'.$key]??'')),0,$length);return $address;}
 static function address_ok($a){return preg_match('/^[a-zA-Z]{2}$/',$a['country'])&&$a['postcode']!==''&&$a['street']!==''&&$a['city']!==''&&$a['region']!=='';}
 static function rates(){ $id=absint($_POST['form_id']??0);if(!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['nonce']??'')),'erm_shippo_quote_'.$id)||get_post_type($id)!=='erm_event'||get_post_status($id)!=='publish')wp_send_json_error(['message'=>'Invalid request'],403);$s=ERM_Plugin::settings($id);if($s['form_type']!=='shop'||empty($s['shipping_live'])||empty($s['fulfillment_shipping'])||!self::configured())wp_send_json_error(['message'=>'Live shipping is not available'],400);$a=self::address_from_post();if(!self::address_ok($a))wp_send_json_error(['message'=>'Enter your full delivery address to see rates.'],400);
  $ip=substr(sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR']??'')),0,100);$limit='erm_shippo_limit_'.md5($id.'|'.$ip);$n=(int)get_transient($limit);if($n>=15)wp_send_json_error(['message'=>'Too many shipping requests. Please try again later.'],429);set_transient($limit,$n+1,10*MINUTE_IN_SECONDS);
  $result=self::request('shipments/',self::shipment($a));if(is_wp_error($result))wp_send_json_error(['message'=>$result->get_error_message()],502);
  $offers=[];foreach((array)($result['rates']??[]) as $rate){if(($rate['currency']??'')!=='USD'||!isset($rate['object_id'],$rate['amount']))continue;$amount=(float)$rate['amount'];if(!is_finite($amount)||$amount<0)continue;$offers[]=['id'=>sanitize_text_field($rate['object_id']),'amount'=>round($amount,2),'carrier'=>sanitize_text_field($rate['provider']??'Carrier'),'service'=>sanitize_text_field($rate['servicelevel']['name']??'Shipping'),'days'=>absint($rate['estimated_days']??0)];}usort($offers,static function($a,$b){return $a['amount']<=>$b['amount'];});$offers=array_slice($offers,0,20);if(!$offers)wp_send_json_error(['message'=>'No carrier rates are available for this address.'],400);
  $token=bin2hex(random_bytes(16));set_transient('erm_shippo_quote_'.$token,['form'=>$id,'address_hash'=>hash('sha256',wp_json_encode($a)),'offers'=>$offers,'test'=>(bool)self::options()['test']],20*MINUTE_IN_SECONDS);wp_send_json_success(['token'=>$token,'rates'=>$offers]);
 }
 static function selected_rate($form,$address){$token=sanitize_text_field(wp_unslash($_POST['erm_shippo_quote_token']??''));$rate_id=sanitize_text_field(wp_unslash($_POST['erm_shippo_rate_id']??''));if(!preg_match('/^[a-f0-9]{32}$/',$token))return new WP_Error('quote','Missing shipping quote');$quote=get_transient('erm_shippo_quote_'.$token);if(!is_array($quote)||$quote['form']!=$form||!hash_equals($quote['address_hash'],hash('sha256',wp_json_encode($address))))return new WP_Error('quote','Shipping quote expired or address changed');foreach($quote['offers'] as $offer)if(hash_equals($offer['id'],$rate_id)){delete_transient('erm_shippo_quote_'.$token);return $offer+['quoted_at'=>time(),'test'=>$quote['test']];}return new WP_Error('quote','Choose a valid shipping service');}
 static function labels_page(){if(!current_user_can('manage_options'))wp_die('Forbidden');echo '<div class="wrap"><h1>Shipping Labels</h1><p>Review shipping orders and explicitly purchase labels. Labels incur charges in live mode. A label can only be purchased once per order.</p>';if(isset($_GET['error']))echo '<div class="notice notice-error"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['error']))).'</p></div>';$entries=get_posts(['post_type'=>'erm_entry','post_status'=>'private','posts_per_page'=>100,'meta_query'=>[['key'=>'_erm_fulfillment','value'=>'shipping']]]);echo '<table class="widefat striped"><thead><tr><th>Order</th><th>Carrier</th><th>Quoted shipping</th><th>Label</th></tr></thead><tbody>';foreach($entries as $e){$rate=(array)get_post_meta($e->ID,'_erm_shippo_rate',true);$label=(array)get_post_meta($e->ID,'_erm_shippo_label',true);echo '<tr><td>#'.(int)$e->ID.' — '.esc_html($e->post_title).'</td><td>'.esc_html(($rate['carrier']??'Manual').' '.($rate['service']??'')).'</td><td>$'.esc_html(number_format((float)get_post_meta($e->ID,'_erm_shipping_cost',true),2)).'</td><td>';if(!empty($label['url']))echo '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($label['url']).'">Print 4×6 PDF</a> — '.esc_html($label['tracking']??'');elseif(!empty($rate['id'])){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" onsubmit="return confirm(\'Purchase this shipping label? Live mode charges your Shippo account.\')"><input type="hidden" name="action" value="erm_shippo_label"><input type="hidden" name="entry" value="'.(int)$e->ID.'">';wp_nonce_field('erm_shippo_label_'.$e->ID);echo '<button class="button button-primary">Purchase 4×6 Label</button></form>';}else echo 'Manual shipping / no Shippo rate';echo '</td></tr>';}echo '</tbody></table></div>';}
 static function label(){if(!current_user_can('manage_options'))wp_die('Forbidden');$id=absint($_POST['entry']??0);check_admin_referer('erm_shippo_label_'.$id);if(get_post_type($id)!=='erm_entry'||get_post_meta($id,'_erm_fulfillment',true)!=='shipping')wp_die('Invalid order');$existing=get_post_meta($id,'_erm_shippo_label',true);if(!empty($existing))wp_die('Label already purchased. Use the existing label.');$rate=(array)get_post_meta($id,'_erm_shippo_rate',true);if(empty($rate['id'])||empty($rate['quoted_at'])||time()-(int)$rate['quoted_at']>6*DAY_IN_SECONDS)wp_die('Rate expired. A new quote is required before purchasing a label.');if((bool)($rate['test']??false)!==(bool)self::options()['test'])wp_die('Test/live mode changed since the quote was generated.');
  $lock='erm_shippo_label_lock_'.$id;if(!add_option($lock,time(),'','no'))wp_die('A label purchase has already been started for this order. Check Shippo before trying again.');$result=self::request('transactions/',['rate'=>$rate['id'],'async'=>false,'label_file_type'=>'PDF_4x6','metadata'=>'Order #'.$id]);if(is_wp_error($result)||($result['status']??'')!=='SUCCESS'){update_option($lock,['needs_review'=>true,'transaction'=>$result['object_id']??'','time'=>time()],false);wp_die('Label purchase was not confirmed. Check your Shippo dashboard before retrying to avoid a duplicate charge.');}
  $label=['transaction'=>sanitize_text_field($result['object_id']??''),'url'=>esc_url_raw($result['label_url']??''),'tracking'=>sanitize_text_field($result['tracking_number']??''),'tracking_url'=>esc_url_raw($result['tracking_url_provider']??''),'purchased_at'=>current_time('mysql'),'test'=>!empty($result['test'])];update_post_meta($id,'_erm_shippo_label',$label);wp_safe_redirect(admin_url('edit.php?post_type=erm_event&page=erm-shipping-labels'));exit;
 }
}
